package v1

import (
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"math"
	"slices"
	"strconv"
	"strings"
	"unicode/utf16"

	"google.golang.org/protobuf/encoding/protojson"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protodesc"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/types/descriptorpb"
	"google.golang.org/protobuf/types/dynamicpb"
)

var errCreateFingerprint = errors.New("canonical Create fingerprint unavailable or schema mismatch")

// Generated by the Rust canonical descriptor exporter, not by the Go runtime's
// descriptor.proto version. A core regression checks every byte against the
// compiled projection; never rewrite or normalize this closure in the SDK.
//
//go:embed create_descriptor.bin
var createDescriptor []byte

// CreateOwnershipKeyFromRequest projects the original binary Create request
// into a receipt/fence key. It clears only request_id on a decoded copy, never changes
// the audited flag, and refuses a descriptor mismatch without a legacy fallback.
// expectedSchema must come from the qualified release's canonical vector manifest.
func CreateOwnershipKeyFromRequest(originalWire []byte, expectedSchema string) (CreateOwnershipKey, error) {
	if len(originalWire) > 4*1024*1024 {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	digest := createFingerprintSchemaDigest()
	if expectedSchema != digest {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	set := &descriptorpb.FileDescriptorSet{}
	if proto.Unmarshal(createDescriptor, set) != nil {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	files, err := protodesc.NewFiles(set)
	if err != nil {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	descriptor, err := files.FindDescriptorByName("openshell.v1.CreateSandboxRequest")
	if err != nil {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	messageDescriptor, ok := descriptor.(protoreflect.MessageDescriptor)
	if !ok {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	request := dynamicpb.NewMessage(messageDescriptor)
	if (proto.UnmarshalOptions{RecursionLimit: 128}).Unmarshal(originalWire, request) != nil {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	requestIDField := request.Descriptor().Fields().ByName("request_id")
	if requestIDField == nil || requestIDField.Kind() != protoreflect.StringKind {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	requestID := request.Get(requestIDField).String()
	if !validOwnershipUUID(requestID) {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	request.Clear(requestIDField)
	canonical, err := canonicalCreateJSON(request)
	if err != nil {
		return CreateOwnershipKey{}, errCreateFingerprint
	}
	hash := sha256.Sum256(canonical)
	return CreateOwnershipKey{RequestID: requestID, Fingerprint: append([]byte(nil), hash[:]...), SchemaDigest: digest}, nil
}

func createFingerprintSchemaDigest() string {
	hash := sha256.Sum256(createDescriptor)
	return hex.EncodeToString(hash[:])
}

// Descriptor ProtoJSON preserves presence, enum names, bytes and int64 strings,
// and omits unknown binary fields. The JCS writer then orders UTF-16 property
// names and emits ECMAScript finite numbers without HTML escaping or a newline.
func canonicalCreateJSON(message proto.Message) ([]byte, error) {
	wire, err := protojson.Marshal(message)
	if err != nil {
		return nil, errCreateFingerprint
	}
	decoder := json.NewDecoder(bytes.NewReader(wire))
	decoder.UseNumber()
	var value any
	if decoder.Decode(&value) != nil {
		return nil, errCreateFingerprint
	}
	var out bytes.Buffer
	if err := writeCreateCanonical(&out, value, 0); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

func writeCreateCanonical(out *bytes.Buffer, value any, depth int) error {
	if depth > 128 {
		return errCreateFingerprint
	}
	switch v := value.(type) {
	case map[string]any:
		keys := make([]string, 0, len(v))
		for key := range v {
			keys = append(keys, key)
		}
		slices.SortFunc(keys, func(a, b string) int { return slices.Compare(utf16.Encode([]rune(a)), utf16.Encode([]rune(b))) })
		out.WriteByte('{')
		for i, key := range keys {
			if i != 0 {
				out.WriteByte(',')
			}
			writeCreateString(out, key)
			out.WriteByte(':')
			if err := writeCreateCanonical(out, v[key], depth+1); err != nil {
				return err
			}
		}
		out.WriteByte('}')
	case []any:
		out.WriteByte('[')
		for i, item := range v {
			if i != 0 {
				out.WriteByte(',')
			}
			if err := writeCreateCanonical(out, item, depth+1); err != nil {
				return err
			}
		}
		out.WriteByte(']')
	case json.Number:
		f, err := strconv.ParseFloat(string(v), 64)
		if err != nil {
			return errCreateFingerprint
		}
		number, err := canonicalCreateNumber(f)
		if err != nil {
			return err
		}
		out.WriteString(number)
	case string:
		writeCreateString(out, v)
	case bool:
		out.WriteString(strconv.FormatBool(v))
	case nil:
		out.WriteString("null")
	default:
		return errCreateFingerprint
	}
	return nil
}

func writeCreateString(out *bytes.Buffer, value string) {
	// encoding/json always escapes U+2028/U+2029 even with HTML escaping off;
	// JCS requires their literal UTF-8 representation, like every non-control rune.
	out.WriteByte('"')
	for _, r := range value {
		switch r {
		case '"', '\\':
			out.WriteByte('\\')
			out.WriteRune(r)
		case '\b':
			out.WriteString(`\b`)
		case '\t':
			out.WriteString(`\t`)
		case '\n':
			out.WriteString(`\n`)
		case '\f':
			out.WriteString(`\f`)
		case '\r':
			out.WriteString(`\r`)
		default:
			if r < 0x20 {
				out.WriteString(`\u00`)
				out.WriteByte("0123456789abcdef"[r>>4])
				out.WriteByte("0123456789abcdef"[r&15])
			} else {
				out.WriteRune(r)
			}
		}
	}
	out.WriteByte('"')
}

func canonicalCreateNumber(value float64) (string, error) {
	if math.IsNaN(value) || math.IsInf(value, 0) {
		return "", errCreateFingerprint
	}
	if value == 0 {
		return "0", nil
	}
	abs := math.Abs(value)
	if abs >= 1e-6 && abs < 1e21 {
		return strconv.FormatFloat(value, 'f', -1, 64), nil
	}
	text := strconv.FormatFloat(value, 'e', -1, 64)
	parts := strings.SplitN(text, "e", 2)
	exponent, err := strconv.Atoi(parts[1])
	if err != nil {
		return "", errCreateFingerprint
	}
	sign := ""
	if exponent >= 0 {
		sign = "+"
	}
	return parts[0] + "e" + sign + strconv.Itoa(exponent), nil
}
